package main

import (
	"bufio"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// These SHA-256 outcomes were generated by the legacy Java worker and frozen
// for Go-only regression testing. This test never needs JVM/JAR/Maven.
func TestFrozenJavaMappingGolden(t *testing.T) {
	t.Setenv("STREAMS_NATIVE_ONLY", "1")
	path := filepath.Join("testdata", "mapping_java_golden.tsv")
	file, err := os.Open(path)
	if err != nil {
		t.Fatalf("open committed Java oracle snapshot: %v", err)
	}
	defer file.Close()
	// Each synthetic scenario has exactly four golden outcomes in this order.
	modes := []string{"1000", "0100", "1010", "0010"}
	expected := make(map[string]map[string]string)
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		line := scanner.Text()
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		parts := strings.Split(line, "\t")
		if len(parts) != 5 || parts[0] == "" {
			t.Fatalf("invalid committed golden row: %q", line)
		}
		if _, exists := expected[parts[0]]; exists {
			t.Fatalf("duplicate Java oracle scenario: %q", parts[0])
		}
		entries := make(map[string]string, len(modes))
		for i, mode := range modes {
			if parts[i+1] != "ERROR" && len(parts[i+1]) != 64 {
				t.Fatalf("invalid Java digest for %q/%s", parts[0], mode)
			}
			entries[mode] = parts[i+1]
		}
		expected[parts[0]] = entries
	}
	if err := scanner.Err(); err != nil { t.Fatal(err) }
	cases := syntheticMappingCases()
	if len(expected) != len(cases) {
		t.Fatalf("frozen oracle has %d scenarios, synthetic suite has %d; regenerate Java snapshot intentionally",
			len(expected), len(cases))
	}
	for _, tc := range cases {
		modesExpected, exists := expected[tc.name]
		if !exists { t.Fatalf("missing Java oracle case %q", tc.name) }
		for _, mode := range modes {
			t.Run(tc.name+"/"+mode, func(t *testing.T) {
				golden := modesExpected[mode]
				m := newMapper([]string{"before => before", tc.path+" => selected", "after => after"},
					map[string]string{"before": "text", "selected": tc.fieldType, "after": "text"}, mode)
				defer m.reference.close()
				if err := m.requireNativeSupport(); err != nil {
					t.Fatalf("strict native compilation failed: %v", err)
				}
				mapped, output, err := m.transform(tc.input)
				if m.referenceCalls.Load() != 0 {
					t.Fatal("JVM-free mapper invoked Java reference")
				}
				if got := m.fallbackAudit.snapshot(); len(got.Samples) != 0 {
					t.Fatalf("unexpected runtime Java fallback: %+v", got.Samples)
				}
				if golden == "ERROR" {
					if err == nil { t.Fatal("Java returned an error but native mapper succeeded") }
					return
				}
				if err != nil { t.Fatalf("Java succeeded but native mapper failed: %v", err) }
				digest, err := mappingGoldenDigest(mapped, output)
				if err != nil { t.Fatal(err) }
				if digest != golden {
					t.Fatalf("PQ mapping or Kafka output differs from frozen Java oracle: Go SHA-256=%s Java SHA-256=%s",
						digest, golden)
				}
			})
		}
	}
}
